"""Measure a same-lane pass from retained original Native pose and frame sources."""
import argparse
import hashlib
import json
import math
from pathlib import Path

FRAMES = 600
RATE_HZ = 20
LANE_Y = (-6.0, 0.0)
CAMERAS = ('overview', 'approach', 'reference_corner', 'driver_reference')


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def source_rows(path):
    if not path.is_file():
        raise ValueError('Missing required source: ' + path.name)
    rows = [json.loads(line) for line in path.read_text().splitlines()]
    if len(rows) != FRAMES:
        raise ValueError('Original source does not contain 600 frames: ' + path.name)
    return rows


def bounds(points):
    if not isinstance(points, list) or len(points) != 4:
        raise ValueError('Original body corners incomplete')
    if any(not isinstance(p, list) or len(p) != 2 or
           any(type(v) not in (int, float) or not math.isfinite(v) for v in p) for p in points):
        raise ValueError('Original body corner invalid')
    return min(p[0] for p in points), max(p[0] for p in points), min(p[1] for p in points), max(p[1] for p in points)


def measure(attempt):
    attempt = Path(attempt)
    paths = {name: attempt / name for name in ('participant-poses.jsonl', 'video_frames.jsonl', 'pass-context.json', 'road.xodr')}
    for name, path in paths.items():
        if not path.is_file():
            raise ValueError('Missing required source: ' + name)
    poses = source_rows(paths['participant-poses.jsonl'])
    frames = source_rows(paths['video_frames.jsonl'])
    context = json.loads(paths['pass-context.json'].read_text())
    if context.get('rider_class') != 'motorcycle' or context.get('passed_class') != 'motor_vehicle':
        raise ValueError('Native participant classifications are not the requested motorcycle and other vehicle')
    if not all((attempt / (name + '.mkv')).is_file() for name in CAMERAS):
        raise ValueError('Missing required four original camera videos')
    if 'one-way-two-lane' not in paths['road.xodr'].read_text():
        raise ValueError('Original one-way multilane road source missing')
    first_behind = first_overlap = first_clear = None
    min_lateral_gap = math.inf
    overlap_frames = 0
    previous_native = -1
    for index, (pose, frame) in enumerate(zip(poses, frames)):
        native = pose.get('native_frame')
        if type(native) is not int or native <= previous_native or frame.get('native_frame') != native:
            raise ValueError('Original Native frame join differs')
        previous_native = native
        if pose.get('video_frame') != index or frame.get('video_frame') != index:
            raise ValueError('Original video frame join differs')
        if abs(pose.get('time_s', -1) - index / RATE_HZ) > 1e-6 or abs(frame.get('time_s', -1) - index / RATE_HZ) > 1e-6:
            raise ValueError('Original frame time differs')
        if frame.get('camera_native_frames') != {name: native for name in CAMERAS}:
            raise ValueError('Four original camera frames are not synchronized')
        rider = bounds(pose.get('rider_body_xy_m'))
        motor = bounds(pose.get('motor_body_xy_m'))
        for body in (rider, motor):
            if body[2] < LANE_Y[0] or body[3] > LANE_Y[1]:
                raise ValueError('Participant body departed shared lane at frame ' + str(index))
        if rider[1] < motor[0] and first_behind is None:
            first_behind = index
        if rider[1] >= motor[0] and rider[0] <= motor[1]:
            overlap_frames += 1
            if first_overlap is None:
                first_overlap = index
            lateral_gap = max(motor[2] - rider[3], rider[2] - motor[3], 0.0)
            min_lateral_gap = min(min_lateral_gap, lateral_gap)
        if rider[0] > motor[1] and first_overlap is not None and first_clear is None:
            first_clear = index
    if first_behind is None or first_overlap is None or first_clear is None or not first_behind < first_overlap < first_clear:
        raise ValueError('Original source does not show a complete same-lane behind-to-ahead pass')
    return {'format': 'c146108-motorcycle-same-lane-pass-measurement-v1',
            'frame_count': FRAMES, 'rate_hz': RATE_HZ, 'shared_lane_bounds_y_m': list(LANE_Y),
            'first_behind_frame': first_behind, 'first_overlap_frame': first_overlap,
            'first_clear_ahead_frame': first_clear, 'longitudinal_overlap_frames': overlap_frames,
            'minimum_lateral_surface_gap_during_overlap_m': min_lateral_gap,
            'source_sha256': {name: sha(path) for name, path in paths.items()},
            'camera_video_sha256': {name: sha(attempt / (name + '.mkv')) for name in CAMERAS},
            'subsection_3_exception_status': 'inapplicable_to_motorcycle_and_car_pair',
            'driver_consent_status': 'unobserved', 'legal_verdict_claimed': False,
            'physical_acceptance_claimed': False}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--attempt', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    if args.output.exists():
        raise ValueError('Use a fresh measurement output')
    result = measure(args.attempt)
    args.output.write_text(json.dumps(result, indent=2, allow_nan=False) + '\n')
    print(json.dumps({'first_overlap_frame': result['first_overlap_frame'],
                      'first_clear_ahead_frame': result['first_clear_ahead_frame'],
                      'legal_verdict_claimed': False}))


if __name__ == '__main__':
    main()

"""Source-bound same-lane following counterpart for the controlled pass."""
import hashlib
import json
from pathlib import Path

from measure_pass import CAMERAS, FRAMES, LANE_Y, RATE_HZ, bounds, source_rows


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def measure(attempt):
    attempt = Path(attempt)
    names = ('participant-poses.jsonl', 'video_frames.jsonl', 'pass-context.json', 'road.xodr')
    paths = {name: attempt / name for name in names}
    for name, path in paths.items():
        if not path.is_file():
            raise ValueError('Missing required source: ' + name)
    poses = source_rows(paths['participant-poses.jsonl'])
    frames = source_rows(paths['video_frames.jsonl'])
    context = json.loads(paths['pass-context.json'].read_text())
    if context.get('rider_class') != 'motorcycle' or context.get('passed_class') != 'motor_vehicle':
        raise ValueError('Following participant classifications differ')
    if 'one-way-two-lane' not in paths['road.xodr'].read_text():
        raise ValueError('One-way two-lane original road missing')
    if any(not (attempt / (camera + '.mkv')).is_file() for camera in CAMERAS):
        raise ValueError('Four original camera sources required')
    gaps = []
    previous_native = -1
    for index, (pose, frame) in enumerate(zip(poses, frames)):
        native = pose.get('native_frame')
        if type(native) is not int or native <= previous_native or frame.get('native_frame') != native:
            raise ValueError('Original Native frame join differs')
        previous_native = native
        if pose.get('video_frame') != index or frame.get('video_frame') != index or \
                abs(pose.get('time_s', -1) - index / RATE_HZ) > 1e-6 or \
                abs(frame.get('time_s', -1) - index / RATE_HZ) > 1e-6 or \
                frame.get('camera_native_frames') != {camera: native for camera in CAMERAS}:
            raise ValueError('Original four-view time/frame join differs')
        rider = bounds(pose.get('rider_body_xy_m'))
        other = bounds(pose.get('motor_body_xy_m'))
        for body in (rider, other):
            if body[2] < LANE_Y[0] or body[3] > LANE_Y[1]:
                raise ValueError('Participant body departed shared lane')
        gap = other[0] - rider[1]
        if gap <= 0:
            raise ValueError('Following source entered longitudinal overlap')
        gaps.append(gap)
    if len(gaps) != FRAMES:
        raise ValueError('Incomplete following source')
    return {'format': 'c146108-motorcycle-same-lane-follow-measurement-v1',
            'frame_count': FRAMES, 'rate_hz': RATE_HZ,
            'minimum_longitudinal_body_gap_m': min(gaps),
            'longitudinal_overlap_frames': 0,
            'same_lane_all_frames': True,
            'source_sha256': {name: sha(path) for name, path in paths.items()},
            'camera_video_sha256': {name: sha(attempt / (name + '.mkv')) for name in CAMERAS},
            'legal_verdict_claimed': False, 'physical_acceptance_claimed': False}

"""Source-gated NRS 486.351(2)-(3) alternative review, without a legal verdict."""
from pathlib import Path
import hashlib
import json

RIDER_CLASSES = {'motorcycle', 'moped', 'trimobile'}
PROHIBITED_ACTIONS = {'abreast', 'overtake', 'pass'}
EXCEPTION_PAIR_CLASSES = {'motorcycle', 'moped'}


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def review(context, source_root):
    """Keep visual geometry separate from identity and driver-consent evidence."""
    if context.get('rider_class') not in RIDER_CLASSES:
        raise ValueError('Rider class needs original blueprint and Chapter 486 review')
    if context.get('other_class') not in RIDER_CLASSES | {'motor_vehicle'}:
        raise ValueError('Other vehicle class needs original identity review')
    action = context.get('observed_action')
    if action not in PROHIBITED_ACTIONS | {'following'}:
        raise ValueError('Observed action must be separately source-classified')
    evidence = context.get('classification_source')
    if not isinstance(evidence, dict) or not evidence.get('path') or not evidence.get('sha256'):
        raise ValueError('Participant classification needs original source hash')
    path = Path(source_root) / evidence['path']
    if not path.is_file() or sha(path) != evidence['sha256']:
        raise ValueError('Participant classification source missing or changed')
    pair_eligible = (context['rider_class'] in EXCEPTION_PAIR_CLASSES and
                     context['other_class'] in EXCEPTION_PAIR_CLASSES and
                     action == 'abreast' and context.get('abreast_count') == 2)
    consent = context.get('driver_consent')
    if consent is not None:
        consent_source = context.get('consent_source')
        if not isinstance(consent_source, dict) or not consent_source.get('path') or not consent_source.get('sha256'):
            raise ValueError('Driver consent cannot be inferred from visual arrangement')
        path = Path(source_root) / consent_source['path']
        if not path.is_file() or sha(path) != consent_source['sha256']:
            raise ValueError('Driver consent source missing or changed')
    return {'observed_action': action,
            'rider_class': context['rider_class'],
            'other_class': context['other_class'],
            'same_lane_prohibition_action_observed': action in PROHIBITED_ACTIONS,
            'subsection_3_pair_eligible': pair_eligible,
            'subsection_3_consent_verified': consent is True if pair_eligible else False,
            'subsection_3_exception_established': pair_eligible and consent is True,
            'consent_unverified': pair_eligible and consent is None,
            'classification_source_sha256': evidence['sha256'],
            'legal_verdict_claimed': False}

